<form method="post" class="row mb-4"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="create"><div class="col-md-2"><label>Payer</label><select name="payer_id" class="form-control" required><?php foreach($payers as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['payer_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Reference</label><input name="reference_number" class="form-control" required></div><div class="col-md-2"><label>Date</label><input type="date" name="payment_date" class="form-control" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><label>Amount</label><input type="number" step=".01" name="amount" class="form-control" required></div><div class="col-md-2"><label>Method</label><select name="payment_method" class="form-control"><option>Bank</option><option>Cheque</option><option>Transfer</option><option>Cash</option><option>Other</option></select></div><div class="col-md-2"><label>Bank Ref.</label><input name="bank_reference" class="form-control"></div><div class="col-12 mt-2"><input name="notes" class="form-control" placeholder="Notes"><button class="btn btn-primary mt-2">Record Remittance</button></div></form>
<h5>Open Claims</h5><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Claim</th><th>Payer</th><th>Approved</th><th>Match Payment</th></tr></thead><tbody><?php foreach($claims as $c):?><tr><td><?=htmlspecialchars($c['claim_number'])?></td><td><?=htmlspecialchars($c['payer_id'])?></td><td>KES <?=number_format($c['total_approved_amount'],2)?></td><td><form method="post" class="form-inline"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="match"><input type="hidden" name="claim_id" value="<?=$c['id']?>"><select name="remittance_id" class="form-control form-control-sm mr-1" required><option value="">Remittance</option><?php foreach($rem as $r):?><option value="<?=$r['id']?>"><?=htmlspecialchars($r['reference_number'])?> — <?=number_format($r['amount_received'],2)?></option><?php endforeach;?></select><input name="paid_amount" type="number" step=".01" class="form-control form-control-sm mr-1" placeholder="Paid" required><input name="remarks" class="form-control form-control-sm mr-1" placeholder="Remarks"><button class="btn btn-sm btn-success">Match</button></form></td></tr><?php endforeach;?></tbody></table></div>
<h5>Remittances</h5><table class="table"><thead><tr><th>Reference</th><th>Payer</th><th>Date</th><th>Received</th><th>Matched</th></tr></thead><tbody><?php foreach($rem as $r):?><tr><td><?=htmlspecialchars($r['reference_number'])?></td><td><?=htmlspecialchars($r['payer_name'])?></td><td><?=htmlspecialchars($r['payment_date'])?></td><td>KES <?=number_format($r['amount_received'],2)?></td><td>KES <?=number_format($r['matched'],2)?></td></tr><?php endforeach;?></tbody></table>
